package com.hs.jxc.sys.service;

import com.hs.jxc.common.api.*;
import com.hs.jxc.common.audit.AuditWriter;
import com.hs.jxc.common.context.RequestContext;
import com.hs.jxc.common.db.*;
import com.hs.jxc.sys.api.*;
import java.time.ZoneId;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Existing country wizard commands backed by durable, isolated configuration snapshots. */
@Service @Transactional
public class CountryConfigurationService {
    private static final List<String> TEMPLATE_PARAMS=List.of("locale","dateFormat","numberFormat","addressRule","enabledModules");
    private static final List<String> PUBLIC_CONFIG=List.of("locale","dateFormat","numberFormat","addressRule","enabledModules","isTest","sourceCountryId","sourceTemplateVersionId","activatedAt","activatedBy","templateModules");
    private Map<String,Object> select(Map<String,Object> values,List<String> keys){var result=new LinkedHashMap<String,Object>();for(String key:keys)if(values.containsKey(key))result.put(key,values.get(key));return result;}
    private Map<String,Object> countryReference(long id){var row=DbRows.camel(rawCountry(id));var cfg=json.readMap(String.valueOf(row.remove("config")));row.putAll(select(cfg,PUBLIC_CONFIG));return row;}

    private final org.springframework.beans.factory.ObjectProvider<com.hs.jxc.sys.imports.ImportHandler> imports;private final JdbcTemplate jdbc;private final AuthorizationService auth;private final DbContext db;private final JsonCodec json;private final AuditWriter audit;private final CountryLifecycle lifecycle;private final ConfigReadinessService readiness;private final Map<String,TemplateStructureContributor> structures;
    public CountryConfigurationService(JdbcTemplate jdbc,AuthorizationService auth,DbContext db,JsonCodec json,AuditWriter audit,CountryLifecycle lifecycle,ConfigReadinessService readiness,List<TemplateStructureContributor> contributors,org.springframework.beans.factory.ObjectProvider<com.hs.jxc.sys.imports.ImportHandler> imports){this.imports=imports;this.jdbc=jdbc;this.auth=auth;this.db=db;this.json=json;this.audit=audit;this.lifecycle=lifecycle;this.readiness=readiness;var registry=new LinkedHashMap<String,TemplateStructureContributor>();for(var c:contributors.stream().sorted(Comparator.comparingInt(TemplateStructureContributor::order).thenComparing(TemplateStructureContributor::key)).toList())if(registry.putIfAbsent(c.key(),c)!=null)throw new IllegalStateException("Duplicate country template structure: "+c.key());this.structures=Collections.unmodifiableMap(registry);}
    private Access global(RequestContext c,boolean write){var neutral=new RequestContext(c.userId(),null,c.traceId(),c.tokenHash());return write?auth.authorizePolicyWrite(neutral,true):auth.authorize(neutral);}
    private Access country(RequestContext c,long id,boolean write,String... permissions){global(c,write);db.apply(id);auth.gate(id,write);var target=new RequestContext(c.userId(),id,c.traceId(),c.tokenHash());var a=auth.authorize(target);if(!a.platformAdmin())a.require(permissions);return a;}
    private Access operator(RequestContext c,long id){var identity=global(c,true);identity.require("sys:country:create");if(!identity.platformAdmin())throw ApiException.forbidden();db.apply(id);auth.gate(id,true);return platformScope(c,id);}
    private Access platformScope(RequestContext c,long id){Set<String> perms=new HashSet<>();for(var mod:PermissionCatalog.tree(imports.orderedStream().flatMap(h->h.types().stream()).toList()))for(Object raw:(List<?>)mod.get("children"))perms.add(String.valueOf(((Map<?,?>)raw).get("code")));Map<String,String>fields=new HashMap<>();FieldPolicyService.GROUPS.forEach(g->fields.put(g,"WRITE"));return new Access(c.userId(),id,true,perms,fields,new DataScope(true,Set.of(),Set.of(),Set.of(),Set.of()),null);}
    private Map<String,Object> rawCountry(long id){var rows=jdbc.queryForList("SELECT * FROM sys_country WHERE id=?",id);if(rows.isEmpty())throw ApiException.notFound();return rows.getFirst();}
    private Map<String,Object> config(long id){return json.readMap(String.valueOf(rawCountry(id).get("config")));}
    private Map<String,Object> countryOut(long id){var r=DbRows.camel(rawCountry(id));var cfg=json.readMap(String.valueOf(r.remove("config")));r.putAll(Map.of("locale","zh-CN","dateFormat","YYYY-MM-DD","numberFormat","1,234.56","enabledModules",List.of(),"isTest",false));r.putAll(select(cfg,PUBLIC_CONFIG));r.put("logisticsDelayToleranceHours",cfg.get("lgs.delay.toleranceHours"));var missing=readiness.check(id,"ACTIVATE");r.put("blockCount",missing.stream().filter(m->"BLOCK".equals(m.get("level"))).count());r.put("warnCount",missing.stream().filter(m->"WARN".equals(m.get("level"))).count());var jobs=jdbc.queryForList("SELECT id FROM sys_country_clone_job WHERE country_id=?",Long.class,id);r.put("cloneJobId",jobs.isEmpty()?null:jobs.getFirst());r.put("sourceCountry",null);r.put("sourceTemplateVersionNo",null);if(cfg.get("sourceCountryId")!=null){long source=Inputs.id(cfg.get("sourceCountryId"));r.put("sourceCountry",countryReference(source));long template=Inputs.id(cfg.get("sourceTemplateVersionId"));db.apply(source);var versions=jdbc.queryForList("SELECT version_no FROM sys_country_template WHERE country_id=? AND id=?",Integer.class,source,template);r.put("sourceTemplateVersionNo",versions.isEmpty()?null:versions.getFirst());db.apply(id);}return r;}
    public List<Map<String,Object>> countries(RequestContext c){var identity=global(c,false);var result=new ArrayList<Map<String,Object>>();for(long id:jdbc.queryForList("SELECT id FROM sys_country ORDER BY id",Long.class)){db.apply(id);auth.gate(id,false);if(identity.platformAdmin()||jdbc.queryForObject("SELECT count(*) FROM sys_user_role WHERE country_id=? AND user_id=?",Integer.class,id,c.userId())>0)result.add(countryOut(id));}return result;}
    public Map<String,Object> get(RequestContext c,long id){country(c,id,false,"sys:country:view");return countryOut(id);}
    public Map<String,Object> params(RequestContext c,long id,Map<String,Object>b){var a=country(c,id,true,"sys:country-param:edit");if(!a.platformAdmin()&&!a.scope().all())throw ApiException.forbidden();lifecycle.requireConfigurationWritable(id);var old=rawCountry(id);var cfg=config(id);String currency=Inputs.text(b,"defaultCurrency",String.valueOf(old.get("default_currency"))),timezone=Inputs.text(b,"timezone",String.valueOf(old.get("timezone")));
        if(!currency.matches("[A-Z]{3}")||jdbc.queryForObject("SELECT count(*) FROM md_currency WHERE code=? AND status='ENABLED'",Integer.class,currency)!=1)throw Inputs.bad("请选择已启用币种");try{ZoneId.of(timezone);}catch(Exception e){throw Inputs.bad("时区不合法");}
        if("ACTIVE".equals(old.get("status"))&&!currency.equals(old.get("default_currency")))throw Inputs.bad("启用后不能修改默认币种");
        for(String key:List.of("locale","dateFormat","numberFormat","isTest","enabledModules","addressRule"))if(b.containsKey(key))cfg.put(key,b.get(key));
        if(b.containsKey("logisticsDelayToleranceHours")){
            Object hours=b.get("logisticsDelayToleranceHours");
            if(!(hours instanceof Number)||!hours.toString().matches("[0-9]{1,6}"))throw Inputs.bad("物流延误容忍时长必须为0至999999的整数小时");
            cfg.put("lgs.delay.toleranceHours",Integer.parseInt(hours.toString()));
        }
        if(!(cfg.getOrDefault("enabledModules",List.of()) instanceof List<?> modules)||modules.stream().anyMatch(m->!(m instanceof String text)||!text.matches("[a-z][a-z0-9-]{0,31}")))throw Inputs.bad("模块配置不合法");
        if(jdbc.update("UPDATE sys_country SET name=?,default_currency=?,timezone=?,config=?::jsonb,version=version+1,updated_at=clock_timestamp() WHERE id=? AND version=?",Inputs.text(b,"name",String.valueOf(old.get("name"))),currency,timezone,json.write(cfg),id,Inputs.version(b))!=1)throw Inputs.conflict();auth.bump(id);audit.append(id,c.userId(),"修改地区参数","country",id,DbRows.camel(old),b,null);return countryOut(id);}
    public Map<String,Object> readiness(RequestContext c,long id,String action){country(c,id,false,"sys:country:view","sys:country-param:edit");return Map.of("missing",readiness.check(id,action));}
    public List<Map<String,Object>> reviews(RequestContext c,long id){country(c,id,false,"sys:country:view","sys:country-param:edit");return jdbc.queryForList("SELECT * FROM sys_country_config_review WHERE country_id=? ORDER BY id",id).stream().map(r->{var out=DbRows.camel(r);out.put("status",out.remove("reviewStatus"));out.put("source","国家模板配置");out.put("reviewedBy",r.get("reviewed_by"));return out;}).toList();}
    public Map<String,Object> review(RequestContext c,long id,long reviewId,Map<String,Object>b){var a=country(c,id,true,"sys:country-param:edit");if(!a.platformAdmin()&&!a.scope().all())throw ApiException.forbidden();lifecycle.requireConfigurationWritable(id);var rs=jdbc.queryForList("SELECT * FROM sys_country_config_review WHERE country_id=? AND id=? FOR UPDATE",id,reviewId);if(rs.isEmpty())throw ApiException.notFound();var r=rs.getFirst();String comment=Inputs.required(b,"comment");if("REVIEWED".equals(r.get("review_status")))return Map.of("id",reviewId,"status","REVIEWED");String key=String.valueOf(r.get("item_key"));
        if(key.equals("doc-number-rules"))applyNumberRules(id,json.readMap(String.valueOf(r.get("payload"))),true);
        var contributor=structures.get(key);if(contributor!=null){contributor.confirm(a.platformAdmin()?platformScope(c,id):a,((Number)r.get("source_template_item_id")).longValue(),comment);if(!contributor.ready(a.platformAdmin()?platformScope(c,id):a,((Number)r.get("source_template_item_id")).longValue()))throw new ApiException(409,"SYS_CONFIG_MISSING","请先在原配置页面补齐本地设置");}
        jdbc.update("UPDATE sys_country_config_review SET review_status='REVIEWED',reviewed_by=?,reviewed_at=clock_timestamp(),comment=? WHERE country_id=? AND id=?",c.userId(),comment,id,reviewId);auth.bump(id);audit.append(id,c.userId(),"复核国家配置","country",id,r,Map.of("reviewId",reviewId,"comment",comment),null);return Map.of("id",reviewId,"status","REVIEWED");}
    public Map<String,Object> activate(RequestContext c,long id){var a=country(c,id,true,"sys:country:activate");if(!a.platformAdmin())throw ApiException.forbidden();var missing=readiness.check(id,"ACTIVATE");if(missing.stream().anyMatch(m->"BLOCK".equals(m.get("level"))))throw new ApiException(409,"SYS_CONFIG_MISSING","还有阻断配置，不能启用国家",Map.of("missing",missing));var cfg=config(id);cfg.put("activatedAt",java.time.Instant.now().toString());cfg.put("activatedBy",c.userId());jdbc.update("UPDATE sys_country SET status='ACTIVE',config=?::jsonb,version=version+1 WHERE id=?",json.write(cfg),id);jdbc.update("UPDATE sys_country_clone_job SET status='DONE' WHERE country_id=?",id);auth.bump(id);audit.append(id,c.userId(),"启用国家","country",id,null,Map.of("status","ACTIVE"),null);return countryOut(id);}
    public Map<String,Object> disable(RequestContext c,long id){var a=country(c,id,true,"sys:country:activate");if(!a.platformAdmin())throw ApiException.forbidden();jdbc.update("UPDATE sys_country SET status='DISABLED',version=version+1 WHERE id=?",id);auth.bump(id);audit.append(id,c.userId(),"停用国家","country",id,null,Map.of("status","DISABLED"),null);return countryOut(id);}
    private List<Map<String,Object>> items(long source,long template){db.apply(source);return jdbc.queryForList("SELECT * FROM sys_country_template_item WHERE country_id=? AND template_id=? ORDER BY id",source,template);}
    private Map<String,Object> templateRaw(long id){for(long country:jdbc.queryForList("SELECT id FROM sys_country ORDER BY id",Long.class)){db.apply(country);var rows=jdbc.queryForList("SELECT * FROM sys_country_template WHERE country_id=? AND id=?",country,id);if(!rows.isEmpty())return rows.getFirst();}throw ApiException.notFound();}
    private Map<String,Object> itemOut(Map<String,Object>r){var out=DbRows.camel(r);out.remove("payload");return out;}
    private Map<String,Object> templateOut(Map<String,Object>r){long source=((Number)r.get("country_id")).longValue(),id=((Number)r.get("id")).longValue();var out=DbRows.camel(r);out.remove("sourceParams");out.put("sourceCountryId",source);out.put("sourceCountryName",rawCountry(source).get("name"));var items=items(source,id).stream().map(this::itemOut).toList();out.put("items",items);out.put("itemCount",items.size());return out;}
    public List<Map<String,Object>> templates(RequestContext c,Map<String,String>q){var identity=global(c,false);if(!identity.platformAdmin()){if(c.countryId()==null)throw ApiException.forbidden();country(c,c.countryId(),false,"sys:template:upgrade","sys:country:view");}var result=new ArrayList<Map<String,Object>>();for(long source:jdbc.queryForList("SELECT id FROM sys_country ORDER BY id",Long.class)){db.apply(source);for(var row:jdbc.queryForList("SELECT * FROM sys_country_template WHERE country_id=? ORDER BY version_no DESC",source)){if(!identity.platformAdmin()&&!"PUBLISHED".equals(row.get("status")))continue;if(q.containsKey("status")&&!q.get("status").equals(row.get("status")))continue;if(q.containsKey("sourceCountryId")&&!q.get("sourceCountryId").equals(String.valueOf(source)))continue;result.add(templateOut(row));}}return result;}
    public Map<String,Object> template(RequestContext c,long id){global(c,false);var r=templateRaw(id);if(!"PUBLISHED".equals(r.get("status"))&&!global(c,false).platformAdmin())throw ApiException.notFound();return templateOut(r);}
    public Map<String,Object> createTemplate(RequestContext c,Map<String,Object>b){var identity=global(c,true);identity.require("sys:template:publish");if(!identity.platformAdmin())throw ApiException.forbidden();long source=Inputs.id(b.get("sourceCountryId"));db.apply(source);auth.gate(source,true);lifecycle.requireTradeActive(source);var snapshot=select(config(source),TEMPLATE_PARAMS);int version=jdbc.queryForObject("SELECT coalesce(max(version_no),0)+1 FROM sys_country_template WHERE country_id=?",Integer.class,source);long id=jdbc.queryForObject("INSERT INTO sys_country_template(country_id,version_no,change_note,source_params,created_by) VALUES(?,?,?,?::jsonb,?) RETURNING id",Long.class,source,version,Inputs.required(b,"changeNote"),json.write(snapshot),c.userId());
        addItem(source,id,"MODULE","modules","启用模块",Map.of("enabledModules",snapshot.getOrDefault("enabledModules",List.of())),false,false);
        var numbers=jdbc.queryForList("SELECT doc_type,prefix,date_pattern,sequence_width,reset_period FROM sys_doc_number_rule WHERE country_id=? ORDER BY doc_type",source).stream().map(DbRows::camel).toList();addItem(source,id,"DOC_NUMBER_RULE","doc-number-rules","单据编号规则",Map.of("rules",numbers),false,false);
        addItem(source,id,"LOCAL_REVIEW","local-finance","当地财务、汇率和金额政策",Map.of("requiresLocalConfiguration",true),true,false);
        addItem(source,id,"LOCAL_REVIEW","local-personnel","当地人员授权与审批配置",Map.of("requiresLocalConfiguration",true),true,false);
        for(var contributor:structures.values())addItem(source,id,contributor.itemType(),contributor.key(),contributor.label(),contributor.snapshot(platformScope(c,source)),contributor.requiresReview(),false);
        addItem(source,id,"EXCLUDED","operational-data","订单、库存成本余额、应收应付、凭证及历史报表",Map.of(),false,true);addItem(source,id,"EXCLUDED","people-banks","原国家人员授权及银行账户",Map.of(),false,true);audit.append(source,c.userId(),"生成国家模板","country-template",id,null,Map.of("versionNo",version),null);return templateOut(templateRaw(id));}
    private long addItem(long source,long template,String type,String key,String label,Map<String,Object>payload,boolean review,boolean sensitive){return jdbc.queryForObject("INSERT INTO sys_country_template_item(country_id,template_id,item_type,item_key,label,payload,requires_review,sensitive) VALUES(?,?,?,?,?,?::jsonb,?,?) RETURNING id",Long.class,source,template,type,key,label,json.write(payload),review,sensitive);}
    public Map<String,Object> publish(RequestContext c,long id){var identity=global(c,true);identity.require("sys:template:publish");if(!identity.platformAdmin())throw ApiException.forbidden();var r=templateRaw(id);long source=((Number)r.get("country_id")).longValue();db.apply(source);auth.gate(source,true);jdbc.update("UPDATE sys_country_template SET status='PUBLISHED',published_by=?,published_at=clock_timestamp() WHERE country_id=? AND id=? AND status='DRAFT'",c.userId(),source,id);audit.append(source,c.userId(),"发布国家模板","country-template",id,null,Map.of("status","PUBLISHED"),null);return templateOut(templateRaw(id));}
    public Map<String,Object> createClone(RequestContext c,Map<String,Object>b){var identity=global(c,true);identity.require("sys:country:create");if(!identity.platformAdmin())throw ApiException.forbidden();long templateId=Inputs.id(b.get("templateId"));var template=templateRaw(templateId);if(!"PUBLISHED".equals(template.get("status")))throw Inputs.bad("请选择已发布模板");long source=((Number)template.get("country_id")).longValue();String code=Inputs.required(b,"targetCode").toUpperCase(Locale.ROOT);if(!code.matches("[A-Z]{2}"))throw Inputs.bad("国家代码应为两位字母");var selected=items(source,templateId).stream().filter(i->!Boolean.TRUE.equals(i.get("sensitive"))).map(i->i.get("id")).toList();var cfg=json.readMap(String.valueOf(template.get("source_params")));cfg.put("sourceCountryId",source);cfg.put("sourceTemplateVersionId",templateId);cfg.put("isTest",Boolean.TRUE.equals(b.get("isTest")));long target=jdbc.queryForObject("INSERT INTO sys_country(code,name,status,config) VALUES(?,?,'DRAFT',?::jsonb) RETURNING id",Long.class,code,Inputs.text(b,"targetName",code),json.write(cfg));db.apply(target);jdbc.update("INSERT INTO sys_authz_epoch(country_id) VALUES(?)",target);auth.gate(target,true);long job=jdbc.queryForObject("INSERT INTO sys_country_clone_job(country_id,source_country_id,template_id,selected_item_ids,created_by) VALUES(?,?,?,?::jsonb,?) RETURNING id",Long.class,target,source,templateId,json.write(selected),c.userId());audit.append(target,c.userId(),"创建国家草稿","country",target,null,Map.of("templateId",templateId),null);return jobOut(c,jobRaw(job));}
    private Map<String,Object> jobRaw(long id){for(long country:jdbc.queryForList("SELECT id FROM sys_country ORDER BY id",Long.class)){db.apply(country);var rows=jdbc.queryForList("SELECT * FROM sys_country_clone_job WHERE country_id=? AND id=?",country,id);if(!rows.isEmpty())return rows.getFirst();}throw ApiException.notFound();}
    private Map<String,Object> jobOut(RequestContext c,Map<String,Object>job){long target=((Number)job.get("country_id")).longValue(),source=((Number)job.get("source_country_id")).longValue();var out=DbRows.camel(job);out.put("selectedItemIds",json.read(String.valueOf(job.get("selected_item_ids")),List.class));out.put("template",templateOut(templateRaw(((Number)job.get("template_id")).longValue())));out.put("sourceCountry",countryReference(source));db.apply(target);out.put("targetCountry",countryOut(target));for(var entry:Map.of("entity","org_entity","warehouse","org_warehouse","store","org_store","book","fin_book").entrySet()){var rows=jdbc.queryForList("SELECT * FROM "+entry.getValue()+" WHERE country_id=? ORDER BY id LIMIT 1",target);out.put(entry.getKey(),rows.isEmpty()?null:DbRows.camel(rows.getFirst()));}out.put("adminUserIds",jdbc.queryForList("SELECT ur.user_id FROM sys_user_role ur JOIN sys_role r ON r.country_id=ur.country_id AND r.id=ur.role_id WHERE ur.country_id=? AND (r.role_type='COUNTRY_ADMIN' OR r.code='COUNTRY_ADMIN') ORDER BY ur.user_id",Long.class,target));return out;}
    public Map<String,Object> cloneJob(RequestContext c,long id){global(c,true).require("sys:country:create");var job=jobRaw(id);operator(c,((Number)job.get("country_id")).longValue());return jobOut(c,job);}
    private Map<String,Object> writableJob(RequestContext c,long id){global(c,true).require("sys:country:create");var job=jobRaw(id);operator(c,((Number)job.get("country_id")).longValue());if(!"DRAFT".equals(job.get("status")))throw new ApiException(409,"SYS_STATE_INVALID","配置草稿已生成，不能修改复制向导");return job;}
    public Map<String,Object> cloneItems(RequestContext c,long id,Map<String,Object>b){var job=writableJob(c,id);long target=((Number)job.get("country_id")).longValue(),source=((Number)job.get("source_country_id")).longValue();var ids=ids(b.get("itemIds"));var available=items(source,((Number)job.get("template_id")).longValue());for(long selected:ids)if(available.stream().noneMatch(i->((Number)i.get("id")).longValue()==selected&&!Boolean.TRUE.equals(i.get("sensitive"))))throw Inputs.bad("模板项不存在或属于禁止复制的敏感数据");db.apply(target);jdbc.update("UPDATE sys_country_clone_job SET selected_item_ids=?::jsonb WHERE country_id=? AND id=?",json.write(ids),target,id);return jobOut(c,jobRaw(id));}
    public Map<String,Object> cloneOrg(RequestContext c,long id,Map<String,Object>b){var job=writableJob(c,id);long target=((Number)job.get("country_id")).longValue();var entity=object(b,"entity");var warehouse=object(b,"warehouse");long entityId=upsertOrg(target,"org_entity",entity,Map.of());upsertOrg(target,"org_warehouse",warehouse,Map.of("entity_id",entityId,"type","WAREHOUSE"));if(b.get("store") instanceof Map<?,?>){var st=object(b,"store");long store=upsertOrg(target,"org_store",st,Map.of("entity_id",entityId));long wh=upsertOrg(target,"org_warehouse",Map.of("code",Inputs.required(st,"code")+"-WH","name",Inputs.required(st,"name")+"门店仓"),Map.of("entity_id",entityId,"store_id",store,"type","STORE"));jdbc.update("UPDATE org_store SET default_warehouse_id=? WHERE country_id=? AND id=?",wh,target,store);}if(b.get("book") instanceof Map<?,?>){var book=object(b,"book");String currency=String.valueOf(rawCountry(target).get("default_currency"));if(currency.isBlank())throw Inputs.bad("请先设置当地币种");jdbc.update("INSERT INTO fin_book(country_id,entity_id,code,name,base_currency,status,created_by) VALUES(?,?,?,?,?,'ACTIVE',?) ON CONFLICT(country_id,code) DO UPDATE SET name=EXCLUDED.name,base_currency=EXCLUDED.base_currency,version=fin_book.version+1",target,entityId,Inputs.required(book,"code"),Inputs.required(book,"name"),currency,c.userId());}audit.append(target,c.userId(),"初始化国家组织","country",target,null,b,null);return jobOut(c,jobRaw(id));}
    private long upsertOrg(long country,String table,Map<String,Object>b,Map<String,Object>extra){var cols=new ArrayList<String>(List.of("country_id","code","name"));var args=new ArrayList<Object>(List.of(country,Inputs.required(b,"code"),Inputs.required(b,"name")));extra.forEach((k,v)->{cols.add(k);args.add(v);});return jdbc.queryForObject("INSERT INTO "+table+"("+String.join(",",cols)+") VALUES("+String.join(",",Collections.nCopies(cols.size(),"?"))+") ON CONFLICT(country_id,code) DO UPDATE SET name=EXCLUDED.name,version="+table+".version+1 RETURNING id",Long.class,args.toArray());}
    public Map<String,Object> cloneAdmin(RequestContext c,long id,Map<String,Object>b){var job=writableJob(c,id);long target=((Number)job.get("country_id")).longValue();var users=ids(b.get("userIds"));if(users.isEmpty())throw Inputs.bad("至少指定一名国家管理员");for(long user:users)if(jdbc.queryForObject("SELECT count(*) FROM sys_user WHERE id=? AND status='ENABLED'",Integer.class,user)!=1)throw Inputs.bad("管理员账号不存在或已停用");var permissions=platformScope(c,target).permissions().stream().filter(p->!Set.of("sys:country:create","sys:country:activate","sys:template:publish","sys:cross-country:view").contains(p)).sorted().toList();long role=jdbc.queryForObject("INSERT INTO sys_role(country_id,code,name,role_type,permissions,field_policies) VALUES(?,'COUNTRY_ADMIN','国家管理员','COUNTRY_ADMIN',?::jsonb,?::jsonb) ON CONFLICT(country_id,code) DO UPDATE SET name=sys_role.name RETURNING id",Long.class,target,json.write(permissions),json.write(platformScope(c,target).fieldGroups()));var prior=jdbc.queryForList("SELECT user_id FROM sys_user_role WHERE country_id=? AND role_id=?",Long.class,target,role);jdbc.update("DELETE FROM sys_user_role WHERE country_id=? AND role_id=?",target,role);for(long previous:prior)if(!users.contains(previous))jdbc.update("DELETE FROM sys_user_data_scope WHERE country_id=? AND user_id=? AND scope_type='COUNTRY_ALL'",target,previous);for(long user:users){jdbc.update("INSERT INTO sys_user_role(country_id,user_id,role_id) VALUES(?,?,?)",target,user,role);if(jdbc.queryForObject("SELECT count(*) FROM sys_user_data_scope WHERE country_id=? AND user_id=? AND scope_type='COUNTRY_ALL'",Integer.class,target,user)==0)jdbc.update("INSERT INTO sys_user_data_scope(country_id,user_id,scope_type,granted_by) VALUES(?,?,'COUNTRY_ALL',?)",target,user,c.userId());jdbc.update("UPDATE sys_user SET version=version+1 WHERE id=?",user);}auth.bump(target);audit.append(target,c.userId(),"指定国家管理员","country",target,Map.of("userIds",prior),Map.of("userIds",users),null);return jobOut(c,jobRaw(id));}
    public Map<String,Object> preview(RequestContext c,long id){global(c,false).require("sys:country:create");var job=jobRaw(id);long target=((Number)job.get("country_id")).longValue(),source=((Number)job.get("source_country_id")).longValue();var selected=ids(json.read(String.valueOf(job.get("selected_item_ids")),List.class));var all=items(source,((Number)job.get("template_id")).longValue());var copy=all.stream().filter(i->selected.contains(((Number)i.get("id")).longValue())&&!Boolean.TRUE.equals(i.get("sensitive"))).map(this::itemOut).toList();var excluded=all.stream().filter(i->!selected.contains(((Number)i.get("id")).longValue())||Boolean.TRUE.equals(i.get("sensitive"))).map(i->{var r=itemOut(i);r.put("reason",Boolean.TRUE.equals(i.get("sensitive"))?"敏感数据，禁止复制":"未勾选");return r;}).toList();db.apply(target);return Map.of("copyList",copy,"excluded",excluded,"missing",readiness.check(target,"ACTIVATE"));}
    public Map<String,Object> apply(RequestContext c,long id){global(c,true).require("sys:country:create");var job=jobRaw(id);long target=((Number)job.get("country_id")).longValue(),source=((Number)job.get("source_country_id")).longValue();var a=operator(c,target);if(!"DRAFT".equals(job.get("status")))return jobOut(c,job);var selected=ids(json.read(String.valueOf(job.get("selected_item_ids")),List.class));var snapshots=items(source,((Number)job.get("template_id")).longValue());db.apply(target);for(var item:snapshots)if(selected.contains(((Number)item.get("id")).longValue()))applyItem(a,item);jdbc.update("UPDATE sys_country_clone_job SET status='APPLIED',applied_at=clock_timestamp() WHERE country_id=? AND id=?",target,id);auth.bump(target);audit.append(target,c.userId(),"生成国家配置草稿","country",target,null,Map.of("jobId",id,"selectedItemIds",selected),null);return jobOut(c,jobRaw(id));}
    private void applyItem(Access a,Map<String,Object>item){if(Boolean.TRUE.equals(item.get("sensitive")))throw Inputs.bad("禁止复制敏感数据");long country=a.requireCountry(),itemId=((Number)item.get("id")).longValue();String key=String.valueOf(item.get("item_key"));var payload=json.readMap(String.valueOf(item.get("payload")));if(key.equals("modules")){var cfg=config(country);cfg.put("templateModules",payload.getOrDefault("enabledModules",List.of()));cfg.putIfAbsent("enabledModules",payload.getOrDefault("enabledModules",List.of()));jdbc.update("UPDATE sys_country SET config=?::jsonb,version=version+1 WHERE id=?",json.write(cfg),country);}else if(key.equals("doc-number-rules")){if(!Boolean.TRUE.equals(item.get("requires_review")))applyNumberRules(country,payload,false);}else if(structures.containsKey(key))structures.get(key).apply(a,payload,itemId);else if(!Set.of("local-finance","local-personnel").contains(key))throw Inputs.bad("该配置结构没有已注册的复制器");if(Boolean.TRUE.equals(item.get("requires_review")))jdbc.update("INSERT INTO sys_country_config_review(country_id,source_template_item_id,config_type,item_key,label,payload) VALUES(?,?,?,?,?,?::jsonb) ON CONFLICT(country_id,source_template_item_id,item_key) DO NOTHING",country,itemId,item.get("item_type"),key,item.get("label"),json.write(payload));}
    private void applyNumberRules(long country,Map<String,Object>payload,boolean update){for(var r:maps(payload.get("rules"))){var old=jdbc.queryForList("SELECT * FROM sys_doc_number_rule WHERE country_id=? AND doc_type=? FOR UPDATE",country,r.get("docType"));if(old.isEmpty())jdbc.update("INSERT INTO sys_doc_number_rule(country_id,doc_type,prefix,date_pattern,sequence_width,reset_period) VALUES(?,?,?,?,?,?)",country,r.get("docType"),r.get("prefix"),r.get("datePattern"),r.get("sequenceWidth"),r.get("resetPeriod"));else if(update){if(!Objects.equals(old.getFirst().get("reset_period"),r.get("resetPeriod"))&&jdbc.queryForObject("SELECT count(*) FROM sys_doc_number_counter WHERE country_id=? AND doc_type=?",Integer.class,country,r.get("docType"))>0)throw Inputs.bad("已发号规则不能改变重置周期，请在本地维护兼容编号规则");jdbc.update("UPDATE sys_doc_number_rule SET prefix=?,date_pattern=?,sequence_width=?,version=version+1 WHERE country_id=? AND doc_type=?",r.get("prefix"),r.get("datePattern"),r.get("sequenceWidth"),country,r.get("docType"));}}}
    public List<Map<String,Object>> upgrades(RequestContext c,long country){country(c,country,false,"sys:template:upgrade");return jdbc.queryForList("SELECT * FROM sys_template_upgrade WHERE country_id=? ORDER BY id DESC",country).stream().map(this::upgradeOut).toList();}
    private Map<String,Object> upgradeOut(Map<String,Object>r){var out=DbRows.camel(r);out.put("diffs",json.read(String.valueOf(r.get("diff")),List.class));out.put("confirmedAt",r.get("decided_at"));out.put("createdBy",r.get("created_by"));long country=((Number)r.get("country_id")).longValue();var from=templateRaw(((Number)r.get("from_template_id")).longValue());var to=templateRaw(((Number)r.get("to_template_id")).longValue());out.put("fromVersionNo",from.get("version_no"));out.put("toVersionNo",to.get("version_no"));db.apply(country);return out;}
    public Map<String,Object> previewUpgrade(RequestContext c,Map<String,Object>b){long target=Inputs.id(b.get("countryId"));var a=country(c,target,true,"sys:template:upgrade");if(!a.platformAdmin()&&!a.scope().all())throw ApiException.forbidden();lifecycle.requireConfigurationWritable(target);var cfg=config(target);long fromId=Inputs.id(cfg.get("sourceTemplateVersionId")),source=Inputs.id(cfg.get("sourceCountryId")),toId=Inputs.id(b.get("toTemplateId"));var old=templateRaw(fromId);var next=templateRaw(toId);if(((Number)next.get("country_id")).longValue()!=source||!"PUBLISHED".equals(next.get("status"))||((Number)next.get("version_no")).intValue()<=((Number)old.get("version_no")).intValue())throw Inputs.bad("请选择相同来源国家的更新已发布版本");var before=items(source,fromId);var after=items(source,toId);var diffs=new ArrayList<Map<String,Object>>();for(var item:after){if(Boolean.TRUE.equals(item.get("sensitive")))continue;var prior=before.stream().filter(i->Objects.equals(i.get("item_key"),item.get("item_key"))).findFirst().orElse(null);if(prior==null||!Objects.equals(String.valueOf(prior.get("payload")),String.valueOf(item.get("payload"))))diffs.add(Map.of("itemKey",item.get("item_key"),"label",item.get("label"),"oldLabel",prior==null?"":prior.get("label"),"changeType",prior==null?"ADDED":"MODIFIED","requiresReview",true));}for(var prior:before)if(!Boolean.TRUE.equals(prior.get("sensitive"))&&after.stream().noneMatch(i->Objects.equals(i.get("item_key"),prior.get("item_key"))))diffs.add(Map.of("itemKey",prior.get("item_key"),"label",prior.get("label"),"oldLabel",prior.get("label"),"changeType","REMOVED","requiresReview",true));db.apply(target);long id=jdbc.queryForObject("INSERT INTO sys_template_upgrade(country_id,from_template_id,to_template_id,source_country_id,diff,created_by) VALUES(?,?,?,?,?::jsonb,?) RETURNING id",Long.class,target,fromId,toId,source,json.write(diffs),c.userId());return upgradeOut(jdbc.queryForMap("SELECT * FROM sys_template_upgrade WHERE country_id=? AND id=?",target,id));}
    public Map<String,Object> confirmUpgrade(RequestContext c,long id){global(c,true);Map<String,Object>upgrade=null;for(long country:jdbc.queryForList("SELECT id FROM sys_country ORDER BY id",Long.class)){db.apply(country);var rs=jdbc.queryForList("SELECT * FROM sys_template_upgrade WHERE country_id=? AND id=?",country,id);if(!rs.isEmpty()){upgrade=rs.getFirst();break;}}if(upgrade==null)throw ApiException.notFound();long target=((Number)upgrade.get("country_id")).longValue();var a=country(c,target,true,"sys:template:upgrade");if(!a.platformAdmin()&&!a.scope().all())throw ApiException.forbidden();lifecycle.requireConfigurationWritable(target);if(!"PREVIEWED".equals(upgrade.get("status")))return upgradeOut(upgrade);if(Inputs.id(config(target).get("sourceTemplateVersionId"))!=((Number)upgrade.get("from_template_id")).longValue())throw Inputs.conflict();long source=((Number)upgrade.get("source_country_id")).longValue();var snapshots=items(source,((Number)upgrade.get("to_template_id")).longValue());db.apply(target);Set<String>changed=new HashSet<>();for(var diff:maps(json.read(String.valueOf(upgrade.get("diff")),List.class)))changed.add(String.valueOf(diff.get("itemKey")));for(var item:snapshots)if(changed.contains(String.valueOf(item.get("item_key")))){var reviewed=new LinkedHashMap<>(item);reviewed.put("requires_review",true);applyItem(a.platformAdmin()?platformScope(c,target):a,reviewed);}var cfg=config(target);cfg.put("sourceTemplateVersionId",upgrade.get("to_template_id"));jdbc.update("UPDATE sys_country SET config=?::jsonb,version=version+1 WHERE id=?",json.write(cfg),target);jdbc.update("UPDATE sys_template_upgrade SET status='CONFIRMED',decided_by=?,decided_at=clock_timestamp() WHERE country_id=? AND id=?",c.userId(),target,id);auth.bump(target);audit.append(target,c.userId(),"确认模板升级","country",target,null,Map.of("upgradeId",id),null);return upgradeOut(jdbc.queryForMap("SELECT * FROM sys_template_upgrade WHERE country_id=? AND id=?",target,id));}
    private List<Long>ids(Object value){if(!(value instanceof Collection<?>items))throw Inputs.bad("ID列表必填");return items.stream().map(Inputs::id).distinct().toList();}
    @SuppressWarnings("unchecked") private Map<String,Object>object(Map<String,Object>b,String key){if(!(b.get(key) instanceof Map<?,?>))throw Inputs.bad(key+"必填");return (Map<String,Object>)b.get(key);}
    @SuppressWarnings("unchecked") private List<Map<String,Object>>maps(Object value){if(!(value instanceof List<?>))throw Inputs.bad("配置结构数组不合法");return (List<Map<String,Object>>)value;}
}
